import{_ as a,o as n,c as t,a2 as e}from"./chunks/framework.B4hAkGey.js";const h=JSON.parse('{"title":"15.1 基础入门：为什么 WebRTC 要自己估带宽","description":"","frontmatter":{},"headers":[],"relativePath":"guide/15-handwritten-gcc/basics.md","filePath":"guide/15-handwritten-gcc/basics.md","lastUpdated":1792683941000}'),p={name:"guide/15-handwritten-gcc/basics.md"};function l(o,s,i,r,d,c){return n(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="_15-1-基础入门-为什么-webrtc-要自己估带宽" tabindex="-1">15.1 基础入门：为什么 WebRTC 要自己估带宽 <a class="header-anchor" href="#_15-1-基础入门-为什么-webrtc-要自己估带宽" aria-label="Permalink to &quot;15.1 基础入门：为什么 WebRTC 要自己估带宽&quot;">​</a></h1><blockquote><p>TCP 的拥塞控制为了「不丢包」可以无限重传，这对实时音视频是致命的。WebRTC 必须在「尽量用满带宽」和「延迟别爆炸」之间走钢丝，Google Congestion Control (GCC) 就是这条钢丝上的平衡杆。</p></blockquote><hr><h2 id="_15-1-1-音视频不能简单用-tcp" tabindex="-1">15.1.1 音视频不能简单用 TCP <a class="header-anchor" href="#_15-1-1-音视频不能简单用-tcp" aria-label="Permalink to &quot;15.1.1 音视频不能简单用 TCP&quot;">​</a></h2><p>想象一个视频通话场景：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>说话人 → 采集 → 编码 → 发送 → 网络 → 接收 → 解码 → 播放</span></span>
<span class="line"><span>                                    ↑</span></span>
<span class="line"><span>                              这里丢了一个包</span></span></code></pre></div><p>TCP 的做法：<strong>停下来，等重传</strong>。这一等就是几百毫秒到几秒。</p><p>对音视频来说，这意味着：</p><ul><li><strong>画面冻结</strong>：用户看到对方卡住不动</li><li><strong>音画不同步</strong>：声音先到，画面后到</li><li><strong>延迟累积</strong>：重传越多，延迟越大，通话变成「对讲机」</li></ul><p>所以 WebRTC 选择 <strong>UDP</strong> 作为传输层，把「要不要重传、怎么重传」的决定权交给应用层自己。</p><p>但 UDP 没有拥塞控制（Congestion Control），如果发送端不管不顾地猛发，路由器队列会被打爆，<strong>所有人一起卡死</strong>。因此 WebRTC 必须在 UDP 之上自己实现一套拥塞控制。</p><hr><h2 id="_15-1-2-拥塞控制的三大目标" tabindex="-1">15.1.2 拥塞控制的三大目标 <a class="header-anchor" href="#_15-1-2-拥塞控制的三大目标" aria-label="Permalink to &quot;15.1.2 拥塞控制的三大目标&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目标</th><th>含义</th><th>冲突点</th></tr></thead><tbody><tr><td><strong>最大化利用率</strong></td><td>尽量把链路带宽用满，别浪费</td><td>发多了会排队</td></tr><tr><td><strong>最小化延迟抖动</strong></td><td>排队延迟不能忽高忽低</td><td>发少了利用率低</td></tr><tr><td><strong>公平性</strong></td><td>多条流共享链路时，别一家独大</td><td>需要全局协调</td></tr></tbody></table><p>这三大目标是<strong>互相矛盾</strong>的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>        高利用率</span></span>
<span class="line"><span>           /\\</span></span>
<span class="line"><span>          /  \\</span></span>
<span class="line"><span>         /    \\</span></span>
<span class="line"><span>        /      \\</span></span>
<span class="line"><span>       /        \\</span></span>
<span class="line"><span>低延迟  ----------  公平性</span></span></code></pre></div><p>GCC 的解法是：<strong>以延迟为主要信号</strong>，因为延迟对用户体验的伤害比丢包更直接。</p><hr><h2 id="_15-1-3-两大流派-loss-based-vs-delay-based" tabindex="-1">15.1.3 两大流派：Loss-based vs Delay-based <a class="header-anchor" href="#_15-1-3-两大流派-loss-based-vs-delay-based" aria-label="Permalink to &quot;15.1.3 两大流派：Loss-based vs Delay-based&quot;">​</a></h2><h3 id="基于丢包-loss-based" tabindex="-1">基于丢包（Loss-based） <a class="header-anchor" href="#基于丢包-loss-based" aria-label="Permalink to &quot;基于丢包（Loss-based）&quot;">​</a></h3><ul><li><strong>代表</strong>：TCP Reno / CUBIC</li><li><strong>思路</strong>：发快点 → 丢包了 → 降速 → 慢慢加回来</li><li><strong>问题</strong>：丢包是<strong>事后</strong>信号，等发现丢包时队列已经满了，延迟早就爆炸</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>发送速率</span></span>
<span class="line"><span>   ↑</span></span>
<span class="line"><span>   │      /\\</span></span>
<span class="line"><span>   │     /  \\</span></span>
<span class="line"><span>   │    /    \\        ← 丢包点</span></span>
<span class="line"><span>   │   /      \\      /</span></span>
<span class="line"><span>   │  /        \\    /</span></span>
<span class="line"><span>   │ /          \\  /</span></span>
<span class="line"><span>   │/            \\/</span></span>
<span class="line"><span>   └────────────────→ 时间</span></span>
<span class="line"><span>     加性增加   乘性减少</span></span></code></pre></div><h3 id="基于延迟-delay-based" tabindex="-1">基于延迟（Delay-based） <a class="header-anchor" href="#基于延迟-delay-based" aria-label="Permalink to &quot;基于延迟（Delay-based）&quot;">​</a></h3><ul><li><strong>代表</strong>：GCC、BBR</li><li><strong>思路</strong>：盯着「排队延迟」的变化趋势，<strong>在丢包之前</strong>就主动降速</li><li><strong>优势</strong>：延迟是<strong>事前</strong>信号，可以在队列打满之前刹车</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>排队延迟</span></span>
<span class="line"><span>   ↑</span></span>
<span class="line"><span>   │         危险区</span></span>
<span class="line"><span>   │       ┌─────┐</span></span>
<span class="line"><span>   │      /       \\</span></span>
<span class="line"><span>   │     /         \\</span></span>
<span class="line"><span>   │    /           \\</span></span>
<span class="line"><span>   │   /             \\</span></span>
<span class="line"><span>   │  /               \\</span></span>
<span class="line"><span>   │ /                 \\</span></span>
<span class="line"><span>   │/                   \\</span></span>
<span class="line"><span>   └──────────────────────→ 时间</span></span>
<span class="line"><span>     预测性减速        恢复</span></span></code></pre></div><hr><h2 id="_15-1-4-google-congestion-control-gcc-的历史与地位" tabindex="-1">15.1.4 Google Congestion Control (GCC) 的历史与地位 <a class="header-anchor" href="#_15-1-4-google-congestion-control-gcc-的历史与地位" aria-label="Permalink to &quot;15.1.4 Google Congestion Control (GCC) 的历史与地位&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时间</th><th>事件</th></tr></thead><tbody><tr><td>2011</td><td>WebRTC 开源，GCC 作为默认拥塞控制器</td></tr><tr><td>2012</td><td>原始论文《A Google Congestion Control Algorithm for Real-Time Communication》发布</td></tr><tr><td>2016</td><td>GCC 升级为 <strong>Trendline Filter</strong> 版本，取代早期的卡尔曼滤波实现</td></tr><tr><td>2021</td><td>RFC 8834 标准化，成为 WebRTC mandatory-to-implement</td></tr></tbody></table><p>GCC 的地位：</p><ul><li>它是 <strong>WebRTC 的默认拥塞控制器</strong>，Chrome、Firefox、Safari 都在用</li><li>它是 <strong>发送端（Sender-side）</strong> 和 <strong>接收端（Receiver-side）</strong> 混合架构</li><li>它证明了 <strong>延迟梯度（Delay Gradient）</strong> 可以作为可靠的拥塞信号</li></ul><hr><h2 id="_15-1-5-发送端码率调整-vs-接收端反馈" tabindex="-1">15.1.5 发送端码率调整 vs 接收端反馈 <a class="header-anchor" href="#_15-1-5-发送端码率调整-vs-接收端反馈" aria-label="Permalink to &quot;15.1.5 发送端码率调整 vs 接收端反馈&quot;">​</a></h2><p>GCC 是<strong>混合架构</strong>，两边分工不同：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>发送端(Sender)                          接收端(Receiver)</span></span>
<span class="line"><span>   │                                       │</span></span>
<span class="line"><span>   │  1. 按目标码率发送 RTP 包              │</span></span>
<span class="line"><span>   │ ────────────────────────────────────&gt; │</span></span>
<span class="line"><span>   │                                       │</span></span>
<span class="line"><span>   │  2. 定期回传 RTCP Feedback             │</span></span>
<span class="line"><span>   │     (到达时间、丢包、抖动)              │</span></span>
<span class="line"><span>   │ &lt;──────────────────────────────────── │</span></span>
<span class="line"><span>   │                                       │</span></span>
<span class="line"><span>   │  3. 本地跑 Delay-based 算法            │</span></span>
<span class="line"><span>   │     (Arrival Filter → Trendline →    │</span></span>
<span class="line"><span>   │      Overuse Detector → AIMD)        │</span></span>
<span class="line"><span>   │                                       │</span></span>
<span class="line"><span>   │  4. 更新目标码率，通知编码器            │</span></span>
<span class="line"><span>   │     &quot;别编超过 X kbps&quot;                  │</span></span></code></pre></div><ul><li><strong>接收端</strong>：负责精确测量每个包的到达时间，通过 RTCP 回传</li><li><strong>发送端</strong>：根据反馈跑算法，决定下一秒的编码码率</li></ul><p>为什么不让接收端直接算？因为<strong>发送端才知道自己编码器的能力边界</strong>（比如不能降到 100 kbps 以下，否则画面全黑）。</p><hr><h2 id="_15-1-6-小结" tabindex="-1">15.1.6 小结 <a class="header-anchor" href="#_15-1-6-小结" aria-label="Permalink to &quot;15.1.6 小结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>概念</th><th>一句话</th></tr></thead><tbody><tr><td>为什么不用 TCP</td><td>重传延迟对实时音视频不可接受</td></tr><tr><td>拥塞控制目标</td><td>用满带宽 + 低延迟 + 公平，三者取平衡</td></tr><tr><td>Loss-based</td><td>事后补救，延迟已爆炸</td></tr><tr><td>Delay-based</td><td>事前预测，在丢包前刹车</td></tr><tr><td>GCC 核心思想</td><td>盯着排队延迟的变化趋势，提前调整码率</td></tr></tbody></table><p>下一章我们将深入 GCC 的算法细节：延迟梯度怎么算、趋势怎么平滑、状态机怎么跳。</p><p>→ <a href="./advanced">15.2 进阶应用：延迟梯度、卡尔曼滤波与状态机</a></p>`,41)])])}const b=a(p,[["render",l]]);export{h as __pageData,b as default};
